WITH filtered AS (SELECT *, CAST(event_time AS DATE) AS event_time_day FROM web_events WHERE event_time > TO_DATE('2023-06-08')) SELECT id, session_id, event_type, page, event_time, duration_sec, LEAD(duration_sec, 2, 0) OVER (PARTITION BY event_type, session_id ORDER BY event_time, id) AS next_duration_sec, COUNT(duration_sec) OVER (PARTITION BY event_type) AS event_type_count_duration_sec, ROW_NUMBER() OVER (PARTITION BY session_id, page ORDER BY duration_sec DESC, id) AS event_seq, AVG(duration_sec) OVER (ORDER BY duration_sec, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS duration_sec_avg_3, NTILE(5) OVER (PARTITION BY event_type, page ORDER BY duration_sec, id) AS duration_sec_bucket FROM filtered WHERE session_id = 2;
